// ActivityLog Activities performed by Admins.
type ActivityLog struct {
	// ActivityDescription A sentence or two describing the activity.
	//
	// Example: Admin updated the app's name to "My App".
	ActivityDescription *string `json:"activity_description,omitempty"`

	// ActivityType Example: app_name_change
	ActivityType *ActivityLogActivityType `json:"activity_type,omitempty"`

	// CreatedAt The time the activity was created.
	//
	// Example: 1671028894
	CreatedAt *int `json:"created_at,omitempty"`

	// ID The id representing the activity.
	//
	// Example: 6
	ID *string `json:"id,omitempty"`

	// Metadata Additional data provided about Admin activity.
	Metadata *ActivityLogMetadata `json:"metadata,omitempty"`

	// PerformedBy Details about the Admin involved in the activity.
	PerformedBy *ActivityLog_PerformedBy `json:"performed_by,omitempty"`
}

// ActivityLogActivityType Example: app_name_change
type ActivityLogActivityType string

// ActivityLog_PerformedBy Details about the Admin involved in the activity.
type ActivityLog_PerformedBy struct {
	// Email The email of the admin.
	//
	// Example: john@example.com
	Email *string `json:"email,omitempty"`

	// ID The id representing the admin.
	//
	// Example: 1295
	ID *string `json:"id,omitempty"`

	// IP The IP address of the admin.
	//
	// Example: 198.51.100.255
	IP *string `json:"ip,omitempty"`

	// Type String representing the object's type. Always has the value `admin`.
	//
	// Example: admin
	Type *string `json:"type,omitempty"`
}

// ActivityLogEventTypeList A list of all activity log event types.
type ActivityLogEventTypeList struct {
	// EventTypes An array of activity log event type strings.
	//
	// Example: ["admin_login_success","admin_logout","app_name_change"]
	EventTypes *[]string `json:"event_types,omitempty"`

	// Type String representing the object's type. Always has the value `activity_log_event_type.list`.
	//
	// Example: activity_log_event_type.list
	Type *string `json:"type,omitempty"`
}

// ActivityLogList A paginated list of activity logs.
type ActivityLogList struct {
	// ActivityLogs An array of activity logs
	ActivityLogs *[]*ActivityLog `json:"activity_logs,omitempty"`

	// Pages Cursor-based pagination is a technique used in the Intercom API to navigate through large amounts of data.
	// A "cursor" or pointer is used to keep track of the current position in the result set, allowing the API to return the data in small chunks or "pages" as needed.
	Pages *CursorPages `json:"pages,omitempty"`

	// Type String representing the object's type. Always has the value `activity_log.list`.
	//
	// Example: activity_log.list
	Type *string `json:"type,omitempty"`
}

// ActivityLogMetadata Additional data provided about Admin activity.
type ActivityLogMetadata struct {
	// After The state of settings or values after the change. Structure varies by activity type.
	After *map[string]interface{} `json:"after,omitempty"`

	// Auto Indicates the state was derived automatically rather than set by an Admin.
	//
	// Example: true
	Auto *bool `json:"auto,omitempty"`

	// AutoChanged Indicates if the status was changed automatically or manually.
	//
	// Example: false
	AutoChanged *string `json:"auto_changed,omitempty"`

	// AwayMode The away mode status which is set to true when away and false when returned.
	//
	// Example: true
	AwayMode *bool `json:"away_mode,omitempty"`

	// AwayStatusReason The reason the Admin is away.
	//
	// Example: 😌 On a break
	AwayStatusReason *string `json:"away_status_reason,omitempty"`

	// Before The state of settings or values before the change. Structure varies by activity type.
	Before *map[string]interface{} `json:"before,omitempty"`

	// Changes The settings altered by the change, keyed by setting name. Only settings whose value actually moved are included, so an unchanged setting is absent rather than present with equal values.
	//
	// Example: {"occupancy_window_minutes":{"after":30,"before":15}}
	Changes *map[string]ActivityLogMetadata_Changes `json:"changes,omitempty"`

	// ConsentID The ID of the impersonation consent.
	//
	// Example: 149673
	ConsentID *int `json:"consent_id,omitempty"`

	// ConversationAssignmentLimit The conversation assignment limit value for an admin.
	//
	// Example: 15
	ConversationAssignmentLimit *int `json:"conversation_assignment_limit,omitempty"`

	// Enabled Indicates if the setting is enabled or disabled.
	//
	// Example: true
	Enabled *bool `json:"enabled,omitempty"`

	// ExpiredAt The timestamp when the impersonation consent expires.
	//
	// Example: 2025-12-04T09:31:57.000Z
	ExpiredAt *time.Time `json:"expired_at,omitempty"`

	// ExternalID The unique identifier for the contact which is provided by the Client.
	//
	// Example: f3b87a2e09d514c6c2e79b9a
	ExternalID *string `json:"external_id,omitempty"`

	// LastActivityAt The time of the Admin's last recorded activity.
	//
	// Example: 1671028894
	LastActivityAt *int `json:"last_activity_at,omitempty"`

	// Mode The mode of the setting (e.g., when_away_only, when_away_and_reassign).
	//
	// Example: when_away_only
	Mode *string `json:"mode,omitempty"`

	// NewState The state after the change. `idle` or `occupied`.
	//
	// Example: occupied
	NewState *string `json:"new_state,omitempty"`

	// PreviousState The state before the change. `idle` or `occupied`, and null when the Admin had not been classified yet.
	//
	// Example: idle
	PreviousState *string `json:"previous_state,omitempty"`

	// ReassignConversations Indicates if conversations should be reassigned while an Admin is away.
	//
	// Example: false
	ReassignConversations *bool `json:"reassign_conversations,omitempty"`

	// SettingType The group of workspace settings the change belongs to, for example `teammate_occupancy` or `automatic_away_mode`.
	//
	// Example: teammate_occupancy
	SettingType *string `json:"setting_type,omitempty"`

	// SignInMethod The way the admin signed in.
	//
	// Example: email_password
	SignInMethod *string `json:"sign_in_method,omitempty"`

	// Source The action that initiated the status change.
	//
	// Example: admin update from web - Admin id: 93
	Source *string `json:"source,omitempty"`

	// Team Details about the team whose assignment limit was changed.
	Team *ActivityLogMetadata_Team `json:"team,omitempty"`

	// TeamAssignmentLimit The team assignment limit value (null if limit was removed).
	//
	// Example: 50
	TeamAssignmentLimit *int `json:"team_assignment_limit,omitempty"`

	// ThresholdMinutes The inactivity window, in minutes, used to classify the Admin.
	//
	// Example: 15
	ThresholdMinutes *int `json:"threshold_minutes,omitempty"`

	// TicketAssignmentLimit The ticket assignment limit value for an admin.
	//
	// Example: 20
	TicketAssignmentLimit *int `json:"ticket_assignment_limit,omitempty"`

	// UpdateBy The ID of the Admin who initiated the activity.
	//
	// Example: 93
	UpdateBy *int `json:"update_by,omitempty"`

	// UpdateByName The name of the Admin who initiated the activity.
	//
	// Example: Joe Example
	UpdateByName *string `json:"update_by_name,omitempty"`
}

